content:
{
  "root_cause": "The dialog's autofocus attribute is not honored when opening via showModal(), causing focus to remain outside the dialog after it opens.",
  "repair_strategy": "After showing the dialog (showModal/show), explicitly focus the element with the autofocus attribute, falling back to the dialog itself if none found.",
  "edits": [
    {
      "path": "js/src/dialog-base.ts",
      "sha256": "365b3e69778c2fdc18db529770b50c1881f0588747bead1c79c46c86f9ca9f1b",
      "before": "  protected _showElement({ modal = true, preventBodyScroll = true }: { modal?: boolean, preventBodyScroll?: boolean } = {}): void {
    this._openedAsModal = modal

    if (modal) {
      this._element.showModal()
    } else {
      this._element.show()
    }

    if (preventBodyScroll) {
      // Lock scroll on the root element (not <body>) so it lands on the same
      // element that carries `scrollbar-gutter: stable`. Co-locating them keeps
      // the gutter reserved while the scrollbar is hidden, so the page doesn't
      // shift (and the ::backdrop covers the gutter instead of leaving a strip).
      document.documentElement.classList.add(CLASS_NAME_OPEN)
    }
  }",
      "after": "  protected _showElement({ modal = true, preventBodyScroll = true }: { modal?: boolean, preventBodyScroll?: boolean } = {}): void {
    this._openedAsModal = modal

    if (modal) {
      this._element.showModal()
    } else {
      this._element.show()
    }

    // Move focus to the autofocus element or first focusable element
    const autofocus = this._element.querySelector('[autofocus]')
    if (autofocus) {
      (autofocus as HTMLElement).focus()
    } else {
      // fallback: focus the dialog itself if it's focusable
      if (this._element !== document.activeElement) {
        this._element.focus()
      }
    }

    if (preventBodyScroll) {
      // Lock scroll on the root element (not <body>) so it lands on the same
      // element that carries `scrollbar-gutter: stable`. Co-locating them keeps
      // the gutter reserved while the scrollbar is hidden, so the page doesn't
      // shift (and the ::backdrop covers the gutter instead of leaving a strip).
      document.documentElement.classList.add(CLASS_NAME_OPEN)
    }
  }"
  }
],
"expected_accessibility_effect": "Keyboard focus moves into the drawer when opened, allowing users to interact with filters without a pointer.",
"functional_risks": [
  "Potential focus theft if autofocus element is not focusable.",
  "Risk of double-focus if browser already moved focus (mitigated by checking existence)."
],
"verification_requirements": [
  "After activating the drawer button with Enter, focus is on #filters-search.",
  "Pressing Tab moves focus to #in-stock checkbox.",
  "Closing the drawer with Escape returns focus to the trigger button."
]
}
